"leader-114-15":{t:"導遊領隊",tt:"訓練測驗",a:"答 <b class='ac'>D 70 分、7 日內補測</b>。職前訓練測驗及格 70 分,不及格 7 日內補測。",s:"訓練及格 70 分、7 日內補測。"},
"leader-114-16":{t:"入出境",tt:"護照條例",a:"答 <b class='ac'>C 護照效期屆滿得延期一次</b>(錯誤)。護照效期屆滿<b class='wr'>不得延期</b>,須換發。",s:"護照效期屆滿不能延期。"},
"leader-114-17":{t:"入出境",tt:"護照換發",a:"答 <b class='ac'>B 護照資料頁記載事項變更</b>(應換發)。",s:"記載事項變更應換發護照。"},
"leader-114-18":{t:"入出境",tt:"護照施行細則",a:"答 <b class='ac'>B ①③④</b>。②護照效期自<b class='wr'>核發</b>日起算(非申請日)。",s:"護照效期自核發日起算。"},
"leader-114-19":{t:"入出境",tt:"役男出境",a:"答 <b class='ac'>D 民國 114 年 11 月 15 日</b>。役男出境申請時點規定。",s:"役男出境申請日=D。"},
"leader-114-20":{t:"入出境",tt:"旅遊警示",a:"答 <b class='ac'>C 外交部</b>。國外旅遊警示分級由外交部發布。",s:"國外旅遊警示=外交部。"},
"leader-114-21":{t:"入出境",tt:"防疫",a:"答 <b class='ac'>D 48 小時</b>。疑似傳染病持續發燒大於 48 小時。",s:"疑似傳染病發燒>48 小時。"},
